      Object.freeze({
        provider: b.provider,
        name: b.name,
        consumer: b.consumer,
        organization: b.organization,
        hosts:
          b.hosts === undefined ? null : Object.freeze(b.hosts.map((h) => Object.freeze(parseSecretBindingHost(h)!))),
      }),
    );
  });
