      .where("id", "=", input.targetTransformationId)
      .where("organization_id", "=", organizationId)
      .executeTakeFirst();
    if (!t) throw connectorRefusals.targetInvalid();
  }
  if ((input.commitMode === "auto") !== (input.commitOnBehalfOf !== null))
