        message: "Name the user an automatic commit acts on behalf of, exactly when the commit mode is automatic.",
      },
    ]);
  if (input.commitOnBehalfOf !== null) {
    const u = await db
      .selectFrom("app_user")
      .select("id")
      .where("id", "=", input.commitOnBehalfOf)
      .where("organization_id", "=", organizationId)
      .where("status", "=", "active")
      .executeTakeFirst();
