): ModelProvider {
  return {
    kind: "http_endpoint",
    modelName: settings.modelName,
    async complete(request, signal) {
      const started = performance.now();
      const elapsed = () => Math.min(600_000, Math.max(0, Math.round(performance.now() - started)));
