import re
def addimport(s, rel="../../support/secret-bindings.ts", what="bindSecrets"):
    m=re.search(r'import [^;]*from "\.\./\.\./support/harness\.ts";\n', s)
    if not m:
        m=list(re.finditer(r'^import [^;]*;\n', s, re.M))[-1]
    return s[:m.end()]+f'import {{ {what} }} from "{rel}";\n'+s[m.end():]

# store-contract
p='apps/api/test/integration/evidence/store-contract.test.ts'; s=open(p).read()
old='''  const registry = createSecretProviderRegistry();
  registry.register(provider);
  return registry;'''
new='''  // F-DG6-181 (T-DG6-BE-Z2): the two references are bound, as IT would, to `storage`, the installation and the fake's
  // host (127.0.0.1), so the store resolves them; the binding itself is tested in secret-binding.test.ts.
  const registry = createSecretProviderRegistry({ bindings: () => STORE_BINDINGS });
  registry.register(provider);
  return registry;'''
assert old in s; s=s.replace(old,new,1)
old='''/** A synthetic provider holding the fake's keys, plus one name that resolves to nothing. */'''
new='''const STORE_BINDINGS = testSecretBindings(
  ["S3_ACCESS", "S3_SECRET"].map((name) => ({
    provider: "test",
    name,
    consumer: "storage" as const,
    organization: null,
    hosts: ["127.0.0.1"],
  })),
);

/** A synthetic provider holding the fake's keys, plus one name that resolves to nothing. */'''
assert old in s; s=s.replace(old,new,1)
s=addimport(s, what="testSecretBindings")
open(p,'w').write(s)

# log-redaction
p='apps/api/test/integration/operations/log-redaction.test.ts'; s=open(p).read()
old='''    const value = await built.secrets.resolve({ provider: "env", name: ENV_SECRET });'''
new='''    // F-DG6-181 (T-DG6-BE-Z2): bound, as IT would, to the assistant setting (installation) at a synthetic host.
    const unbind = bindSecrets([
      { name: ENV_SECRET, consumer: "assistant", organization: null, hosts: ["model.example.invalid"] },
    ]);
    const value = await built.secrets
      .resolve(
        { provider: "env", name: ENV_SECRET },
        { consumer: "assistant", organizationId: null, host: { hostname: "model.example.invalid", port: 443 } },
      )
      .finally(unbind);'''
assert old in s; s=s.replace(old,new,1)
s=addimport(s)
open(p,'w').write(s)
EOF
